import { expect, test, uniqueName } from "../../fixtures";

function isoDateFromToday(days: number): string {
  const date = new Date();
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

function insuranceCertificate(expiry: string): string {
  return `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`;
}

const cases = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
] as const;

for (const { days, include } of cases) {
  test(
    `insurance expiring in ${days} days ${include ? "is" : "is not"} flagged as expiring soon`,
    { tag: "@REV-08" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const vendorRes = await member.post("/api/vendors", {
        data: {
          name: uniqueName("Expiring Insurance"),
          category: "logistics",
          contact_email: "ops@expiring-insurance.example",
        },
      });
      expect(vendorRes.status(), await vendorRes.text()).toBe(201);
      const vendor = (await vendorRes.json()) as { id: string };

      const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: "insurance.txt",
            mimeType: "text/plain",
            buffer: Buffer.from(insuranceCertificate(isoDateFromToday(days))),
          },
        },
      });
      expect(uploadRes.status(), await uploadRes.text()).toBe(201);
      const document = (await uploadRes.json()) as { id: string };

      // Wait for background extraction so the expiry date is available to the flag rule.
      await expect
        .poll(
          async () => {
            const docRes = await member.get(`/api/documents/${document.id}`);
            expect(docRes.status(), await docRes.text()).toBe(200);
            return ((await docRes.json()) as { status: string }).status;
          },
          { timeout: 30_000 },
        )
        .toBe("extracted");

      // Act
      const response = await member.get(`/api/vendors/${vendor.id}`);

      // Assert
      expect(response.status(), await response.text()).toBe(200);
      const body = (await response.json()) as { flags: string[] };
      if (include) {
        expect(body.flags, await response.text()).toContain("insurance_expiring_soon");
      } else {
        expect(body.flags, await response.text()).not.toContain("insurance_expiring_soon");
      }
    },
  );
}
